insert into public.kb_documents (id, tenant_id, slug, title, content) values ('0733cfce-989c-5500-9852-cf40b21b2816', '11fc6851-09e5-5cff-91e4-5a5f38a515c8', 'contact-and-hours', 'Contact and Support Hours', '# Contact and Support Hours

- Our AI support assistant answers emails and chats 24/7. You can ask for a human at any time.
- Human support is available Monday–Saturday, 8 am–8 pm Pacific. Escalated requests are answered within one business day.
- We support English, Spanish and French.
- We will never ask for your password or full card number.
')
